# !/usr/bin/env python
# coding: utf-8
"""Score candidate formulas by library formula-frequency harmony.

Uses a LocalOutlierFactor model over library formula distributions to rank
FormulaFinder candidates during Feature elucidation.
"""

from collections import defaultdict

import numpy as np
from elucidation.binning import bin_for_mass
from elucidation.conveniences import pickle_dump, qw, describe
from elucidation.chemFacts import fmla_mass
from elucidation.chemFacts import is_good_dbe, split_fmla
from elucidation.formulaFinder import FormulaFinder
from elucidation.tableLoaders import harmony_cache_loader, ff_dbe_loader
from elucidation.libraryService import LibraryService
from sklearn.neighbors import LocalOutlierFactor


# This would only be used for evaluation, which takes 20 min or so.  Not much point in repeating it!
def get_ff_fmlas():
    try:
        ff_dbe = ff_dbe_loader()
    except Exception as e:
        print("rebuilding")
        (large_ints, large_bins, small_ints, small_masses, options) = harmony_cache_loader()
        start_at = large_bins[bin_for_mass(100)]
        end_at = large_bins[bin_for_mass(999)]
        results = []
        ff = FormulaFinder.get_instance(
            209
        )  # TODO: something to fix here? Or is it library-agnostic?
        for i in range(start_at, end_at):
            results.append(ff.formula_from_int(large_ints[i]))
        ff_dbe = [f for f in results if is_good_dbe(f)]
        pickle_dump("ff_dbe.pkl", ff_dbe)
    return ff_dbe


class FormulaScorer:
    """Singleton scorer that ranks formulas by library harmony."""

    __instance__ = None

    @staticmethod
    def get_instance(lib_id=None):  # This is independent of library.
        if FormulaScorer.__instance__ is None:
            FormulaScorer.__instance__ = FormulaScorer()
        return FormulaScorer.__instance__

    def __init__(self):
        if FormulaScorer.__instance__:
            raise Exception("try again with FormulaScorer.get_instance()")
        try:
            self.lof, self.percentiles = harmony_cache_loader()
            return
        except Exception as e:
            harmony_cache_file = "harmony.pkl"
            print(e)
            print("rebuilding", harmony_cache_file)

            uniq_lib_fmlas = LibraryService.get_instance().get_uniq_fmlas(209)

            # Build training array
            X = np.array(
                [
                    self.vectorize_fmla_for_harmony(fmla)[0]
                    for fmla in uniq_lib_fmlas
                    if self.ff_possible(fmla)
                ]
            )
            # Perturb it so it doesn't match queries that might come later -- a no-no.
            X[:, 0] += 0.001
            # Build scorer
            lof = LocalOutlierFactor(novelty=True)
            lof.fit(X)
            # Unperturb training set, so now we can query with them.
            X[:, 0] -= 0.001
            # Get scores for training set and percentiles of scores
            dec = lof.decision_function(X)
            percentiles = np.array(
                list(describe(dec, percentiles=np.linspace(0, 1, 101)))[4:-1]
            )  # drop max, count, etc.
            pickle_dump(harmony_cache_file, (lof, percentiles))
            self.lof, self.percentiles = lof, percentiles

    # used during table building.
    def evaluate(self):
        ff_fmlas = get_ff_fmlas()
        scores = list(map(self.fmla_harmony, ff_fmlas))
        return describe(scores, percentiles=np.linspace(0, 1, 101))

    @staticmethod
    def ff_possible(fmla):
        """
        True if the fmla only contains elements that are generated by the formula finder.
        (There's no reason to model the other formulas.)
        :param fmla: string formula to check.
        :return: boolean
        """
        charge, atoms = split_fmla(fmla)
        good_atoms = set(qw("C H N O S Cl P I F Br"))
        bad_atoms = [k for k in atoms.keys() if k not in good_atoms]
        return not bad_atoms

    @staticmethod
    def vectorize_fmla_for_harmony(s):
        charge, counts = split_fmla(s)
        total_count = sum(counts.values())
        masses = {k: v * fmla_mass(k) for k, v in counts.items()}
        total_mass = sum(masses.values())
        count_ratios = defaultdict(float)
        count_ratios.update({k: v / total_count for k, v in counts.items()})
        mass_ratios = defaultdict(float)
        mass_ratios.update({k: v / total_mass for k, v in masses.items()})
        return np.array(
            [count_ratios[k] for k in "CHON"] + [mass_ratios[k] for k in "CHON"]
        ).reshape(1, -1)

    def fmla_harmony(self, s):
        x = self.lof.decision_function(self.vectorize_fmla_for_harmony(s))[0]
        return np.digitize(x, self.percentiles)
